package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class Document_title_TriageGen1Test {

    @Test
    public void title_NoTitleElement_ReturnsEmptyString() {
        // Arrange
        Document document = new Document("baseUri");

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleElement_ReturnsTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("Test Title")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("Test Title", actual);
    }

    @Test
    public void title_TitleElementWithWhitespace_ReturnsTrimmedTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("   Test Title   ")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("Test Title", actual);
    }

    @Test
    public void title_NullTitleElement_ReturnsEmptyString() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title"));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_NoElements_ReturnsEmptyString() {
        // Arrange
        Document document = new Document("baseUri");
        Elements elements = document.getElementsByTag("title");
        elements.clear();

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleElementMultipleWhitespace_ReturnsTrimmedTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("   Test Title   ")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("Test Title", actual);
    }

    @Test
    public void title_TitleElementNullText_ReturnsEmptyString() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode(null)));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleElementNullTextWhitespace_ReturnsTrimmedTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("   ")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleElementMultipleTitleTags_ReturnsFirstTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("Test Title 1")));
        document.appendChild(document.createElement("title").appendChild(document.createTextNode("Test Title 2")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("Test Title 1", actual);
    }

    @Test
    public void title_NoTitleTags_ReturnsEmptyString() {
        // Arrange
        Document document = new Document("baseUri");

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleTagWithAttribute_ReturnsTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createElement("tag")));

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }

    @Test
    public void title_TitleTagWithAttributeWhitespace_ReturnsTrimmedTitleText() {
        // Arrange
        Document document = new Document("baseUri");
        document.appendChild(document.createElement("title").appendChild(document.createElement("tag").appendChild(document.createTextNode("   "))))

        // Act
        String actual = document.title();

        // Assert
        assertEquals("", actual);
    }
}
